package main

import (
	"regexp"
	"strconv"
)

func ValidateCPF(cpf string) bool {
	if matched, _ := regexp.MatchString(`^\d{11}$`, cpf); !matched {
		return false
	}
	if matched, _ := regexp.MatchString(`^(\d)\1{10}$`, cpf); matched {
		return false
	}
	sum := 0
	for i := 0; i < 9; i++ {
		digit, _ := strconv.Atoi(string(cpf[i]))
		sum += digit * (10 - i)
	}
	rev := 11 - (sum % 11)
	if rev == 10 || rev == 11 {
		rev = 0
	}
	lastD9, _ := strconv.Atoi(string(cpf[9]))
	if rev != lastD9 {
		return false
	}
	sum = 0
	for i := 0; i < 10; i++ {
		digit, _ := strconv.Atoi(string(cpf[i]))
		sum += digit * (11 - i)
	}
	rev = 11 - (sum % 11)
	if rev == 10 || rev == 11 {
		rev = 0
	}
	lastD10, _ := strconv.Atoi(string(cpf[10]))
	return rev == lastD10
}

